export type FlowErrorCode = (typeof FlowErrorCode)[keyof typeof FlowErrorCode];
/** A flow name must be a single safe path segment (no '/', '\\', '..', leading dot). */
/**
 * ONE safe path segment: the guard for anything that becomes a single directory or file name.
 *
 * Session ids and run ids are this. They are joined into `.reticle/sessions/<id>/` and written to,
 * and a session LABEL is supplied by the tab — so a separator here is a tab choosing where on disk
 * Reticle writes. Flow names were this too until they became namespaced, and the two guards shared
 * one pattern; widening the flow pattern silently widened these, which a test caught immediately.
 * They answer different questions and now have different patterns: a flow name may be a path, a
 * session id may never be one.
 */
export declare const SAFE_SEGMENT_PATTERN: RegExp;
/**
 * A flow name: one or more `/`-separated segments.
 *
 * Namespaced because the replay grammar addresses documents by path — `onboarding/signup` is how a
 * composite names the sub-journey it invokes, and the protocol's `FlowNameSchema` has said so since
 * grammar v2. This pattern is the PERSISTENCE half, and while it stayed single-segment
 * `reticle_flow_save` refused every name the language is built on. Found by driving a composite:
 * recording worked, closing the boundary worked, saving it was refused.
 *
 * Traversal is impossible by CONSTRUCTION rather than by a filter. No segment may contain a dot at
 * all, so `..` cannot be spelled; every segment must START with a letter or digit, so a leading,
 * trailing or doubled separator cannot either. That is stronger than checking for `..`, because
 * there is no encoding of it left to miss.
 */
export declare const FLOW_NAME_PATTERN: RegExp;
/**
 * The outcome of replaying an on-disk flow by re-resolving its
 * semantic anchors against the live DOM. `drift` (an anchor missed → contract changed) is
 * cleanly separated from `error` (the flow could not load or an action failed) and `ok`.
 */
export declare const ReplayStatus: {
    readonly OK: "ok";
    readonly DRIFT: "drift";
    readonly ERROR: "error";
};
export type ReplayStatus = (typeof ReplayStatus)[keyof typeof ReplayStatus];
/**
 * Why an anchor failed to resolve at replay time (the "whose fault is
 * it" reason kind). Drives the human `reason` sentence and whether a nearest-match is offered.
 */
export declare const DriftReason: {
    readonly TESTID_NOT_FOUND: "testid_not_found";
    readonly SIGNAL_NOT_OBSERVED: "signal_not_observed";
    readonly COMPONENT_NOT_FOUND: "component_not_found";
    readonly STATE_MISMATCH: "state_mismatch";
    /**
     * The step carries DEGRADED_ANCHOR_ROLE — no anchor was ever resolvable, so nothing was queried.
     * Distinct from TESTID_NOT_FOUND deliberately: "your element disappeared" and "this step never had
     * an element bound to it" need different fixes, and reporting the second as the first sent heal
     * hunting for the nearest testid to the literal word "unresolved".
     */
    readonly ANCHOR_DEGRADED: "anchor_degraded";
    /**
     * The step's anchor resolved and its action ran; the testid its `expect.element` names was absent
     * afterwards. Distinct from TESTID_NOT_FOUND for the same reason ANCHOR_DEGRADED is: "the element
     * you clicked is gone" and "the thing you asserted afterwards never appeared" need different
     * fixes, and reporting the second as the first sends the caller looking for a renamed anchor on a
     * step whose anchor was fine.
     */
    readonly EXPECT_ELEMENT_NOT_FOUND: "expect_element_not_found";
    /**
     * The step's `expect.net` named a request that was still ON THE WIRE when the budget ended.
     *
     * A blind spot, not a failed assertion. Reported as SIGNAL_NOT_OBSERVED it reads as "the request
     * you declared never happened", which sends a reader hunting a feature that works — the live
     * verdict path already refuses to grade a named in-flight request as a miss, and replay was the
     * one reader that had not asked the question. The fix for this drift is a longer budget or a
     * faster endpoint; the fix for SIGNAL_NOT_OBSERVED is the handler behind the action.
     */
    readonly NET_STILL_IN_FLIGHT: "net_still_in_flight";
};
export type DriftReason = (typeof DriftReason)[keyof typeof DriftReason];
/**
 * Did the step's anchor resolve and its action RUN, leaving only the declared consequence unmet?
 *
 * The three reasons below all mean the same thing about the app's state: the element was found, the
 * action was dispatched, and the page is where the step left it. Only the assertion failed. The
 * other reasons mean the anchor itself was never resolved, so the page is somewhere the flow never
 * described and every later step would run against a state nobody predicted.
 *
 * That difference is what lets a replay CONTINUE past a failure without turning one wrong result
 * into several — see the sweep option on replayFlow. Halting on both was correct while there was no
 * way to tell them apart; it stopped a 6-step bug sweep at its first defect and reported the other
 * five as `notAttempted`.
 */
export declare function isConsequenceDrift(reason: DriftReason): boolean;
